import numpy as np

def bounce_effect(close, mid, k):
    """Monthly committed means: closes, closes with the wait, mids."""
    m = lambda px, w: float(np.mean(run(px, k, w, 126))) / 6
    return m(close, 0), m(close, 1), m(mid, 0)


def net_of_costs(payoff, n_trips, c):
    """Payoff after a cost c on each of 4 trades per round trip."""
    return payoff - 4 * c * n_trips


def breakeven_cost(gross_cycle, trips):
    """Cost per trade that makes the net return zero."""
    return gross_cycle / (4 * trips)
